'use strict';

const assert = require('node:assert/strict');
const {createHash} = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const {loadDefaultCampaign} = require('../../scripts/aichi-comparison-campaign.cjs');
const {planAichi} = require('../evaluation/aichi-pilot.cjs');
const {runMatch} = require('./headless.cjs');

/** @param {unknown} obj */
function sha(obj) {
  return createHash('sha256').update(JSON.stringify(obj)).digest('hex');
}

/**
 * Remove only metadata generated by the optional post-choice pass probe.
 * No actions, prompts, game state or baseline observational information may
 * be normalized away. This is an action-equivalence audit, not win evidence.
 * @param {object} completed Pinned engine result from one source-locked trial.
 */
function counterfactualFingerprint(completed) {
  const ordinaryTrace = completed.decisionTrace?.map(entry => {
    const {attackPassProbe, ...actualAction} = entry;
    return actualAction;
  });
  const meaningful = {
    seed: completed.seed,
    engine: completed.engine,
    rules: completed.rules,
    deckHashes: completed.deckHashes,
    finished: completed.finished,
    endReason: completed.endReason,
    winner: completed.winner,
    turns: completed.turns,
    actions: completed.actions,
    firstTurnSlot: completed.firstTurnSlot,
    verifiedByDrawLog: completed.verifiedByDrawLog,
    prizesRemaining: completed.prizesRemaining,
    actionCounts: completed.actionCounts,
    actionsBySeat: completed.actionsBySeat,
    cardsPlayedBySeat: completed.cardsPlayedBySeat,
    attackTrace: completed.attackTrace,
    abilityTrace: completed.abilityTrace,
    decisionTrace: ordinaryTrace,
    terminalTransition: completed.terminalTransition,
    finalState: completed.finalState
  };
  return {hash: sha(meaningful), actualState: meaningful};
}

/**
 * One fixed, source-ranked trial replayed with identical engine cards,
 * independent RNG streams and policy actions, changing only the optional
 * read-only attack probe. Throws if the action/board path changes.
 * @param {object} [settings]
 */
function runPassProbeNoninterference(settings = {}) {
  const sourceDir = path.resolve(__dirname, '../../results/aichi-2026');
  const candidate = JSON.parse(fs.readFileSync(
    path.join(sourceDir, 'candidate-hood-shadow-rider.json'), 'utf8'
  ));
  const protocol = 'independent-slots-v2';
  const campaign = loadDefaultCampaign(protocol);
  const trial = campaign.trials.find(item =>
    item.trialId === 'pilot:2:0:hood-shield-v1:B');
  assert.ok(trial, 'Published fixed campaign must retain rank2 Hood B trial');
  const mapping = planAichi(candidate, {
    allowEquivalentBasicEnergies: true,
    allowJapanesePromoHooks: true
  });
  const rank2 = mapping.opponents.find(opponent => opponent.rank === 2);
  assert.ok(mapping.candidate.cards && rank2?.cards);
  assert.equal(mapping.candidate.cards.length, 60);
  assert.equal(rank2.cards.length, 60);
  const options = {
    label: 'Aichi source-ranked Hood-vs-Vileplume post-choice observation',
    deckA: rank2.cards,
    deckB: mapping.candidate.cards,
    seed: trial.seed,
    maxActions: settings.maxActions ?? 600,
    strictPromptValidation: true,
    forestSealSearchCorrection: true,
    doubleDragonRecovery: true,
    supporterDecisionCorrection: true,
    isolatePolicyRandomness: true,
    captureDecisionTrace: true,
    leleEntryAbilityLockCorrection: true,
    radiantGateLockCorrection: true
  };

  // Verify the ordinary path, then the opt-in observer. The clone accepts
  // speculative attacks only after a Pass decision has already been made.
  const baseline = runMatch({...options, captureAttackPassProbes: false});
  const observed = runMatch({...options, captureAttackPassProbes: true});
  const base = counterfactualFingerprint(baseline);
  const withProbe = counterfactualFingerprint(observed);
  assert.equal(withProbe.hash, base.hash,
    'Optional cloned attack-pass observation changed the source-ranked game');
  assert.ok(observed.attackPassProbeCount >= 1,
    'Must actually run post-choice checks for this to test noninterference');

  return {
    kind: 'source-ranked-cloned-pass-observer-noninterference-v1',
    trialId: trial.trialId,
    sourceManifestDigest: mapping.manifestDigest,
    candidateSourceDigest: trial.candidateDigest,
    opponentSourceDigest: trial.opponentDigest,
    engine: baseline.engine,
    seed: trial.seed,
    policy: baseline.policy,
    fixedFlags: options,
    actionAndStateFingerprint: base.hash,
    observedClonedPasses: observed.attackPassProbeCount,
    observationBuckets: observed.attackPassProbeBuckets,
    actualGameActions: baseline.actions,
    actualTurns: baseline.turns,
    actualEngineWinner: baseline.winner,
    flagsDifferedOnlyInOptionalPassObservation: true,
    verifiedEqualActionAndStateHistory: true,
    competitiveQualification: false,
    caveat: 'Only one source-locked weak-bot game, under pinned engine behavior; action-equivalence of a post-choice audit is not paper rules or opponent policy fidelity.'
  };
}

if (require.main === module) {
  process.stdout.write(JSON.stringify(runPassProbeNoninterference(), null, 2) + '\n');
}
module.exports = {counterfactualFingerprint, runPassProbeNoninterference};
